// carryForwardToNewShadowBranch creates a new shadow branch at the current HEAD
// containing the remaining uncommitted files and metadata. This preserves session
// context for files that weren't part of the just-completed commit, ensuring that
// subsequent commits also get their own checkpoint.
func (s *ManualCommitStrategy) carryForwardToNewShadowBranch(
	logCtx context.Context,
	repo *git.Repository,
	state *SessionState,
	remainingFiles []string,
) {
	store := checkpoint.NewGitStore(repo)

	metadataDir := paths.SessionMetadataDirFromSessionID(state.SessionID)
	metadataDirAbs := filepath.Join(state.WorktreePath, metadataDir)

	result, err := store.WriteTemporary(context.Background(), checkpoint.WriteTemporaryOptions{
		SessionID:         state.SessionID,
		BaseCommit:        state.BaseCommit, // Already updated to new HEAD by condensation
		WorktreeID:        state.WorktreeID,
		ModifiedFiles:     remainingFiles, // All remaining files as "modified"
		MetadataDir:       metadataDir,
		MetadataDirAbs:    metadataDirAbs,
		CommitMessage:     "carry forward: uncommitted session files",
		IsFirstCheckpoint: false, // Only include specified files, not all dirty files
	})
	if err != nil {
		logging.Warn(logCtx, "carry-forward: failed to create shadow branch",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return
	}

	if result.Skipped {
		logging.Debug(logCtx, "carry-forward: skipped (dedup)",
			slog.String("session_id", state.SessionID),
		)
		return
	}

	state.FilesTouched = remainingFiles
	state.StepCount = 1

	logging.Info(logCtx, "carry-forward: created shadow branch with remaining files",
		slog.String("session_id", state.SessionID),
		slog.Int("remaining_files", len(remainingFiles)),
		slog.String("base_commit", truncateHash(state.BaseCommit)),
	)
}

