// TestPostCommit_ActiveSession_Condenses verifies that PostCommit on an
// ACTIVE session condenses immediately (no deferral) and stays ACTIVE.
func TestPostCommit_ActiveSession_Condenses(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-postcommit-active"

	// Initialize session and save a checkpoint so there is shadow branch content
