// TestPostCommit_ShadowBranch_PreservedWhenUncondensedActiveExists verifies that
// the shadow branch is preserved when an ACTIVE session has no new content to condense
// (e.g., it was just started and hasn't saved a checkpoint yet).
// The IDLE session with content IS condensed, but the branch stays because
// the active session still references it.
func TestPostCommit_ShadowBranch_PreservedWhenUncondensedActiveExists(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	idleSessionID := "test-postcommit-idle-multi"
	activeSessionID := "test-postcommit-active-multi"

	// Initialize the idle session with a checkpoint (has content on shadow branch)
	setupSessionWithCheckpoint(t, s, repo, dir, idleSessionID)

	// Get worktree path and base commit from the idle session
	idleState, err := s.loadSessionState(idleSessionID)
	require.NoError(t, err)
	worktreePath := idleState.WorktreePath
	baseCommit := idleState.BaseCommit
	worktreeID := idleState.WorktreeID

	// Set idle session to IDLE phase
	idleState.Phase = session.PhaseIdle
	idleState.LastInteractionTime = nil
	require.NoError(t, s.saveSessionState(idleState))

	// Create a second session with the SAME base commit and worktree (concurrent session)
	// This session has NO actual content on the shadow branch (just state file).
	now := time.Now()
	activeState := &SessionState{
		SessionID:           activeSessionID,
		BaseCommit:          baseCommit,
		WorktreePath:        worktreePath,
		WorktreeID:          worktreeID,
		StartedAt:           now,
		Phase:               session.PhaseActive,
		LastInteractionTime: &now,
		StepCount:           1,
	}
	require.NoError(t, s.saveSessionState(activeState))

	// Create a commit WITH the checkpoint trailer
	commitWithCheckpointTrailer(t, repo, dir, "d4e5f6a1b2c3")

	// Run PostCommit
	err = s.PostCommit()
	require.NoError(t, err)

	// Verify the ACTIVE session's phase stays ACTIVE
	activeState, err = s.loadSessionState(activeSessionID)
	require.NoError(t, err)
	assert.Equal(t, session.PhaseActive, activeState.Phase,
		"ACTIVE session should stay ACTIVE on GitCommit")

	// Verify the IDLE session actually condensed (entire/checkpoints/v1 branch should exist)
	idleState, err = s.loadSessionState(idleSessionID)
	require.NoError(t, err)
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after IDLE session condensation")
	require.NotNil(t, sessionsRef)

	// Verify IDLE session's StepCount was reset by condensation
	assert.Equal(t, 0, idleState.StepCount,
		"IDLE session StepCount should be reset after condensation")

	// ACTIVE session was NOT condensed (no new content on shadow branch),
	// so its StepCount is unchanged.
	assert.Equal(t, 1, activeState.StepCount,
		"ACTIVE session StepCount should be unchanged (no content to condense)")

	// The old shadow branch is preserved because the active session was not condensed.
	// Note: BaseCommit is updated to the new HEAD, but the shadow branch still
	// carries the old commit hash name (migration happens on next SaveChanges).
	oldShadowBranch := getShadowBranchNameForCommit(baseCommit, worktreeID)
	refName := plumbing.NewBranchReferenceName(oldShadowBranch)
	_, err = repo.Reference(refName, true)
	assert.NoError(t, err,
		"shadow branch should be preserved when an uncondensed active session exists")
}

