// commitSpecificFilesWithTrailer creates a commit that stages and commits only
// the specified files, with the Entire-Checkpoint trailer.
func commitSpecificFilesWithTrailer(t *testing.T, repo *git.Repository, checkpointIDStr string, files ...string) {
	t.Helper()

	cpID := id.MustCheckpointID(checkpointIDStr)

	wt, err := repo.Worktree()
	require.NoError(t, err)

	for _, f := range files {
		_, err = wt.Add(f)
		require.NoError(t, err)
	}

	commitMsg := "test commit\n\n" + trailers.CheckpointTrailerKey + ": " + cpID.String() + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  time.Now(),
		},
	})
	require.NoError(t, err, "commit with checkpoint trailer should succeed")
}

// TestPostCommit_ActiveSession_CarriesForwardRemainingFiles verifies that when
// an ACTIVE session has 3 files touched but only 2 are committed, a new shadow
// branch is created at the new HEAD with the remaining file.
func TestPostCommit_ActiveSession_CarriesForwardRemainingFiles(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-carry-forward"

	// Create metadata directory with a transcript file
	metadataDir := ".entire/metadata/" + sessionID
	metadataDirAbs := filepath.Join(dir, metadataDir)
	require.NoError(t, os.MkdirAll(metadataDirAbs, 0o755))

	transcript := `{"type":"human","message":{"content":"create three files"}}
{"type":"assistant","message":{"content":"creating A.txt, B.txt, C.txt"}}
`
	require.NoError(t, os.WriteFile(
		filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		[]byte(transcript), 0o644))

	// Create three files
	require.NoError(t, os.WriteFile(filepath.Join(dir, "A.txt"), []byte("file A"), 0o644))
	require.NoError(t, os.WriteFile(filepath.Join(dir, "B.txt"), []byte("file B"), 0o644))
	require.NoError(t, os.WriteFile(filepath.Join(dir, "C.txt"), []byte("file C"), 0o644))

	// SaveChanges with all 3 files as new
	err = s.SaveChanges(SaveContext{
		SessionID:      sessionID,
		ModifiedFiles:  []string{},
		NewFiles:       []string{"A.txt", "B.txt", "C.txt"},
		DeletedFiles:   []string{},
		MetadataDir:    metadataDir,
		MetadataDirAbs: metadataDirAbs,
		CommitMessage:  "Checkpoint with 3 files",
		AuthorName:     "Test",
		AuthorEmail:    "test@test.com",
	})
	require.NoError(t, err)

	// Set phase to ACTIVE
	state, err := s.loadSessionState(sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(state))

	// Verify FilesTouched has all 3 files
	assert.ElementsMatch(t, []string{"A.txt", "B.txt", "C.txt"}, state.FilesTouched)

	// Commit only A.txt and B.txt (C.txt remains uncommitted)
	commitSpecificFilesWithTrailer(t, repo, "a1b2c3d4e5f6", "A.txt", "B.txt")

	// Run PostCommit
	err = s.PostCommit()
	require.NoError(t, err)

	// Verify condensation happened
	_, err = repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after condensation")

	// Verify state was updated with carry-forward
	state, err = s.loadSessionState(sessionID)
	require.NoError(t, err)
	assert.Equal(t, session.PhaseActive, state.Phase, "phase should stay ACTIVE")
	assert.Equal(t, 1, state.StepCount, "StepCount should be 1 (carry-forward checkpoint)")
	assert.Equal(t, []string{"C.txt"}, state.FilesTouched,
		"FilesTouched should contain only the remaining uncommitted file")

	// Verify new shadow branch exists at the new HEAD
	newShadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	refName := plumbing.NewBranchReferenceName(newShadowBranch)
	_, err = repo.Reference(refName, true)
	assert.NoError(t, err, "new shadow branch should exist at new HEAD for carry-forward")
}

// TestPostCommit_ActiveSession_NoCarryForward_WhenAllFilesCommitted verifies
// that when all session files are included in the commit, no carry-forward
// happens and FilesTouched is nil with StepCount 0.
func TestPostCommit_ActiveSession_NoCarryForward_WhenAllFilesCommitted(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}
	sessionID := "test-no-carry-forward"

	// Create metadata directory with a transcript file
	metadataDir := ".entire/metadata/" + sessionID
	metadataDirAbs := filepath.Join(dir, metadataDir)
	require.NoError(t, os.MkdirAll(metadataDirAbs, 0o755))

	transcript := `{"type":"human","message":{"content":"create two files"}}
{"type":"assistant","message":{"content":"creating A.txt, B.txt"}}
`
	require.NoError(t, os.WriteFile(
		filepath.Join(metadataDirAbs, paths.TranscriptFileName),
		[]byte(transcript), 0o644))

	// Create two files
	require.NoError(t, os.WriteFile(filepath.Join(dir, "A.txt"), []byte("file A"), 0o644))
	require.NoError(t, os.WriteFile(filepath.Join(dir, "B.txt"), []byte("file B"), 0o644))

	// SaveChanges with both files
	err = s.SaveChanges(SaveContext{
		SessionID:      sessionID,
		ModifiedFiles:  []string{},
		NewFiles:       []string{"A.txt", "B.txt"},
		DeletedFiles:   []string{},
		MetadataDir:    metadataDir,
		MetadataDirAbs: metadataDirAbs,
		CommitMessage:  "Checkpoint with 2 files",
		AuthorName:     "Test",
		AuthorEmail:    "test@test.com",
	})
	require.NoError(t, err)

	// Set phase to ACTIVE
	state, err := s.loadSessionState(sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	require.NoError(t, s.saveSessionState(state))

	// Verify FilesTouched has both files
	assert.ElementsMatch(t, []string{"A.txt", "B.txt"}, state.FilesTouched)

	// Record old shadow branch name
	oldShadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)

	// Commit both files (all session files included)
	commitSpecificFilesWithTrailer(t, repo, "b1b2b3b4b5b6", "A.txt", "B.txt")

	// Run PostCommit
	err = s.PostCommit()
	require.NoError(t, err)

	// Verify condensation happened
	_, err = repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after condensation")

	// Verify state was reset (no carry-forward)
	state, err = s.loadSessionState(sessionID)
	require.NoError(t, err)
	assert.Equal(t, session.PhaseActive, state.Phase, "phase should stay ACTIVE")
	assert.Equal(t, 0, state.StepCount, "StepCount should be 0 (no carry-forward)")
	assert.Nil(t, state.FilesTouched, "FilesTouched should be nil (all files committed)")

	// Old shadow branch should be deleted
	refName := plumbing.NewBranchReferenceName(oldShadowBranch)
	_, err = repo.Reference(refName, true)
	assert.Error(t, err, "old shadow branch should be deleted after condensation")
}

