	assert.ElementsMatch(t, []string{"C.txt", "D.txt"}, state.FilesTouched,
		"FilesTouched should only contain C.txt and D.txt after reset")

	// --- Commit and condense (round 2) ---
	checkpointID2 := "b1b2b3b4b5b6"
