// filesChangedInCommit returns the set of files changed in a commit by diffing against its parent.
func filesChangedInCommit(commit *object.Commit) map[string]struct{} {
	result := make(map[string]struct{})

	commitTree, err := commit.Tree()
	if err != nil {
		return result
	}

	var parentTree *object.Tree
	if commit.NumParents() > 0 {
		parent, err := commit.Parent(0)
		if err != nil {
			return result
		}
		parentTree, err = parent.Tree()
		if err != nil {
			return result
		}
	}

	if parentTree == nil {
		// Initial commit — all files are new
		if iterErr := commitTree.Files().ForEach(func(f *object.File) error {
			result[f.Name] = struct{}{}
			return nil
		}); iterErr != nil {
			return result
		}
		return result
	}

	changes, err := parentTree.Diff(commitTree)
	if err != nil {
		return result
	}
	for _, change := range changes {
		name := change.To.Name
		if name == "" {
			name = change.From.Name
		}
		result[name] = struct{}{}
	}
	return result
}

// subtractFiles returns files that are NOT in the exclude set.
func subtractFiles(files []string, exclude map[string]struct{}) []string {
	var remaining []string
	for _, f := range files {
		if _, excluded := exclude[f]; !excluded {
			remaining = append(remaining, f)
		}
	}
	return remaining
}

// carryForwardToNewShadowBranch creates a new shadow branch at the current HEAD
// containing the remaining uncommitted files and all session metadata.
// This enables the next commit to get its own unique checkpoint.
func (s *ManualCommitStrategy) carryForwardToNewShadowBranch(
	logCtx context.Context,
	repo *git.Repository,
	state *SessionState,
	remainingFiles []string,
) {
	store := checkpoint.NewGitStore(repo)

	metadataDir := paths.SessionMetadataDirFromSessionID(state.SessionID)
	metadataDirAbs := filepath.Join(state.WorktreePath, metadataDir)

	result, err := store.WriteTemporary(context.Background(), checkpoint.WriteTemporaryOptions{
		SessionID:         state.SessionID,
		BaseCommit:        state.BaseCommit,
		WorktreeID:        state.WorktreeID,
		ModifiedFiles:     remainingFiles,
		MetadataDir:       metadataDir,
		MetadataDirAbs:    metadataDirAbs,
		CommitMessage:     "carry forward: uncommitted session files",
		IsFirstCheckpoint: false,
	})
	if err != nil {
		logging.Warn(logCtx, "post-commit: carry-forward failed",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()),
		)
		return
	}
	if result.Skipped {
		logging.Debug(logCtx, "post-commit: carry-forward skipped (no changes)",
			slog.String("session_id", state.SessionID),
		)
		return
	}

	// Update state for the carry-forward checkpoint.
	// CheckpointTranscriptStart = 0 is intentional: prompt-level carry-forward means
	// the next condensation re-processes the full transcript so the checkpoint is self-contained.
	state.FilesTouched = remainingFiles
	state.StepCount = 1
	state.CheckpointTranscriptStart = 0
	state.LastCheckpointID = ""

	logging.Info(logCtx, "post-commit: carried forward remaining files",
		slog.String("session_id", state.SessionID),
		slog.Int("remaining_files", len(remainingFiles)),
	)
}

	return content.Transcript, nil
}

// InitializeSession creates session state for a new session.
// This is called during UserPromptSubmit hook to set up tracking for the session.
// For auto-commit strategy, this creates a SessionState file in .git/entire-sessions/
// to track CheckpointTranscriptStart (transcript offset) across checkpoints.
// agentType is the human-readable name of the agent (e.g., "Claude Code").
// transcriptPath is the path to the live transcript file (for mid-session commit detection).
// userPrompt is the user's prompt text (stored truncated as FirstPrompt for display).
func (s *AutoCommitStrategy) InitializeSession(sessionID string, agentType agent.AgentType, transcriptPath string, userPrompt string) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get current HEAD commit to track as base
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}

	baseCommit := head.Hash().String()

	// Check if session state already exists (e.g., session resuming)
	existing, err := LoadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to check existing session state: %w", err)
	}
	if existing != nil {
		// Session already initialized — update last interaction time on every prompt submit
		now := time.Now()
		existing.LastInteractionTime = &now

		// Backfill FirstPrompt if empty (for sessions
		// created before the first_prompt field was added, or resumed sessions)
		if existing.FirstPrompt == "" && userPrompt != "" {
			existing.FirstPrompt = truncatePromptForStorage(userPrompt)
		}

		if err := SaveSessionState(existing); err != nil {
			return fmt.Errorf("failed to update session state: %w", err)
		}
		return nil
	}

	// Create new session state
	now := time.Now()
	state := &SessionState{

	// Create new session state
	now := time.Now()
	state := &SessionState{
		SessionID:           sessionID,
		CLIVersion:          buildinfo.Version,
		BaseCommit:          baseCommit,
		StartedAt:           now,
		LastInteractionTime: &now,
		StepCount:           0,
		// CheckpointTranscriptStart defaults to 0 (start from beginning of transcript)
		FilesTouched:   []string{},
		AgentType:      agentType,
		TranscriptPath: transcriptPath,
		FirstPrompt:    truncatePromptForStorage(userPrompt),
	}

	if err := SaveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

	return nil
}

